  'help.type.security': 'Beveiliging',
  'help.type.other': 'Overig',
  'help.faq.cantLogin.q': 'Ik kan niet inloggen op mijn account',
  'help.faq.cantLogin.a': 'Zorg ervoor dat je het juiste e-mailadres en wachtwoord gebruikt. Als je je wachtwoord bent vergeten, klik dan op "Wachtwoord vergeten?" op het inlogscherm. Als het probleem aanhoudt, maak een ondersteuningsticket aan.',
  'help.faq.notReceiving.q': 'Ik ontvang geen e-mails',
  'help.faq.notReceiving.a': 'Controleer eerst je Spam-map. Zorg ervoor dat je opslag niet vol is. Als het probleem aanhoudt, controleer dan of de afzender het juiste e-mailadres heeft en maak een ondersteuningsticket aan.',
  'help.faq.cantSend.q': 'Ik kan geen e-mails verzenden',
  'help.faq.cantSend.a': 'Controleer je internetverbinding en of het e-mailadres van de ontvanger correct is. Controleer of je bijlagen hebt die te groot zijn (max 25MB). Probeer het over een paar minuten opnieuw.',
  'help.faq.forgotPassword.q': 'Ik ben mijn wachtwoord vergeten',
  'help.faq.forgotPassword.a': 'Op het inlogscherm, klik op "Wachtwoord vergeten?" en volg de instructies om je wachtwoord via je herstel-e-mailadres opnieuw in te stellen.',
  'help.faq.accountSecurity.q': 'Ik denk dat mijn account is gehackt',
  'help.faq.accountSecurity.a': 'Verander onmiddellijk je wachtwoord. Controleer je Verzonden map op berichten die je niet hebt verzonden. Zet twee-factor-authenticatie aan in Instellingen > Beveiliging. Maak indien nodig een dringende ondersteuningsaanvraag aan.',
  'help.faq.appAccess.q': 'Hoe krijg ik toegang tot de app op mobiel?',
  'help.faq.appAccess.a': 'Je kunt Chatyy openen via elke mobiele browser op chatyy.com.br, of download onze app uit de app store van je apparaat.',

  // Privacy modal
  'privacy.title': 'Privacybeleid',
  'privacy.subtitle': 'Hoe we jouw gegevens beschermen en verwerken',
  'privacy.lastUpdated': 'Laatst bijgewerkt: maart 2026',
  'privacy.dataCollection.title': 'Gegevensverzameling',
  'privacy.dataCollection.body': 'We verzamelen alleen de informatie die nodig is om onze e-mailservice te bieden: je naam, e-mailadres en de inhoud van berichten die je verzendt en ontvangt. We verkopen of delen je persoonlijke gegevens niet met derden voor marketingdoeleinden.',
  'privacy.dataUsage.title': 'Hoe We Jouw Gegevens Gebruiken',
  'privacy.dataUsage.body': 'Jouw gegevens worden uitsluitend gebruikt om de e-mailservice te beheren en te verbeteren, inclusief het afleveren van berichten, het filteren van spam, het bieden van AI-gestuurde functies (met jouw toestemming) en het handhaven van de beveiliging van je account.',
  'privacy.dataSecurity.title': 'Gegevensbeveiliging',
  'privacy.dataSecurity.body': 'We gebruiken industriestandaard encryptie (TLS/SSL) voor alle gegevens in transit en in rust. Sessies zijn beschermd met versleutelde tokens en CSRF-bescherming. We controleren regelmatig onze beveiligingspraktijken.',
  'privacy.cookies.title': 'Cookies & Lokale Opslag',
  'privacy.cookies.body': 'We gebruiken essentiële cookies en lokale opslag om je sessie te behouden, je voorkeuren (thema, taal) te onthouden en een naadloze ervaring te bieden. We gebruiken geen trackingcookies van derden.',
  'privacy.thirdParties.title': 'Diensten van Derden',
  'privacy.thirdParties.body': 'We kunnen diensten van derden gebruiken voor specifieke functionaliteit zoals AI-functies (Anthropic Claude) en pushmeldingen. Deze diensten zijn gebonden aan hun eigen privacybeleid en verwerken alleen de minimale gegevens die nodig zijn.',
  'privacy.rights.title': 'Jouw Rechten',
  'privacy.rights.body': 'Je hebt het recht om je persoonlijke gegevens op elk moment in te zien, te corrigeren, te exporteren of te verwijderen. Je kunt je gegevens beheren via Instellingen of door contact op te nemen met ons ondersteuningsteam.',
  'privacy.contact.title': 'Neem Contact Met Ons Op',
  'privacy.contact.body': 'Voor vragen over privacy of gegevensverzoeken, neem contact met ons op via privacy@chatyy.com.br. We reageren binnen 30 dagen.',

  // Terms modal
  'terms.title': 'Servicevoorwaarden',
  'terms.subtitle': 'Richtlijnen voor het gebruik van Chatyy',
  'terms.lastUpdated': 'Laatst bijgewerkt: maart 2026',
  'terms.acceptance.title': 'Acceptatie van Voorwaarden',
  'terms.acceptance.body': 'Door toegang te krijgen tot of gebruik te maken van Chatyy, ga je akkoord met deze Servicevoorwaarden. Als je het niet eens bent met een deel van deze voorwaarden, mag je de service niet gebruiken.',
  'terms.services.title': 'Beschrijving van Diensten',
  'terms.services.body': 'Chatyy biedt e-mailcommunicatiediensten, waaronder het verzenden, ontvangen en beheren van e-mails, samen met AI-gestuurde functies, kalenderintegratie en videoconferentiemogelijkheden.',
  'terms.accounts.title': 'Gebruikersaccounts',
  'terms.accounts.body': 'Je bent verantwoordelijk voor het behouden van de beveiliging van je accountgegevens. Je mag je wachtwoord niet delen of ongeautoriseerde toegang tot je account toestaan. Je moet minimaal 13 jaar oud zijn om deze service te gebruiken.',
  'terms.conduct.title': 'Acceptabel Gebruik',
  'terms.conduct.body': 'Je gaat ermee akkoord de service niet te gebruiken voor het verzenden van spam, malware, phishing of enige illegale inhoud. Je mag niet proberen toegang te krijgen tot de accounts van andere gebruikers of de service-infrastructuur te verstoren.',
  'terms.content.title': 'Inhoudseigendom',
  'terms.content.body': 'Je behoudt het eigendom van alle inhoud die je creëert en verzendt via de service. We claimen geen eigendom over je e-mails of bijlagen. We kunnen inhoud verwerken zoals nodig is om de service te bieden.',
  'terms.limitation.title': 'Beperking van Aansprakelijkheid',
  'terms.limitation.body': 'Chatyy wordt "zoals het is" aangeboden. We streven naar 99,9% uptime, maar garanderen geen ononderbroken service. We zijn niet aansprakelijk voor enige indirecte, incidentele of gevolgschade die voortvloeit uit jouw gebruik van de service.',
  'terms.termination.title': 'Accountbeëindiging',
  'terms.termination.body': 'We kunnen accounts opschorten of beëindigen die deze voorwaarden schenden. Je kunt je account op elk moment verwijderen via Instellingen. Na beëindiging worden je gegevens binnen 30 dagen verwijderd.',
  'terms.changes.title': 'Wijzigingen in Voorwaarden',
  'terms.changes.body': 'We kunnen deze voorwaarden van tijd tot tijd bijwerken. We zullen je op de hoogte stellen van belangrijke wijzigingen via e-mail of in-app melding. Voortgezet gebruik van de service na wijzigingen betekent acceptatie van de bijgewerkte voorwaarden.',

